package vn.cinema.controller;
import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import vn.cinema.dto.*;import vn.cinema.dto.CinemaRequests.*;import vn.cinema.service.CinemaService;
@RestController public class CinemaController{private final CinemaService s;public CinemaController(CinemaService s){this.s=s;}
 @GetMapping("/api/cinemas") public Object cinemas(){return Api.ok(s.cinemas());}@GetMapping("/api/cinemas/{id}") public Object cinema(@PathVariable long id){return Api.ok(s.cinema(id));}@PostMapping("/api/cinemas") public Object create(@Valid @RequestBody CinemaInput r){return Api.ok(s.saveCinema(null,r));}@PutMapping("/api/cinemas/{id}") public Object update(@PathVariable long id,@Valid @RequestBody CinemaInput r){return Api.ok(s.saveCinema(id,r));}@DeleteMapping("/api/cinemas/{id}") public Object delete(@PathVariable long id){s.deleteCinema(id);return Api.ok("Đã xóa rạp");}
 @GetMapping("/api/rooms") public Object rooms(){return Api.ok(s.rooms());}@GetMapping("/api/rooms/{id}") public Object room(@PathVariable long id){return Api.ok(s.room(id));}@GetMapping("/api/rooms/{id}/seats") public Object seats(@PathVariable long id){return Api.ok(s.seats(id));}@PostMapping("/api/rooms") public Object create(@Valid @RequestBody RoomInput r){return Api.ok(s.saveRoom(null,r));}@PutMapping("/api/rooms/{id}") public Object update(@PathVariable long id,@Valid @RequestBody RoomInput r){return Api.ok(s.saveRoom(id,r));}@DeleteMapping("/api/rooms/{id}") public Object deleteRoom(@PathVariable long id){s.deleteRoom(id);return Api.ok("Đã xóa phòng");}
 @PostMapping("/api/rooms/{id}/generate-seats") public Object generate(@PathVariable long id,@Valid @RequestBody Generate r){return Api.ok(s.generate(id,r));}@PutMapping("/api/seats/{id}") public Object updateSeat(@PathVariable long id,@Valid @RequestBody SeatInput r){return Api.ok(s.seat(id,r));}
 @GetMapping("/internal/cinemas/{id}")public Object internalCinema(@PathVariable long id){return s.cinema(id);}@GetMapping("/internal/rooms/{id}")public Object internalRoom(@PathVariable long id){return s.room(id);}@GetMapping("/internal/rooms/{id}/seats")public Object internalSeats(@PathVariable long id){return s.seats(id);}
}